const FullCatalog = () => {
  const [search, setSearch] = useState('')
  const [pricingFilter, setPricingFilter] = useState('all')
  const q = search.trim().toLowerCase()

  // Filter each category. Empty categories hide entirely so the accordion
  // stays tight while typing.
  const filteredCats = useMemo(() => {
    return catalog.categories
      .map((cat) => {
        const apis = cat.apis.filter((a) => {
          if (pricingFilter === 'free' && a.pricing !== 'free') return false
          if (pricingFilter === 'paid' && a.pricing !== 'paid') return false
          if (pricingFilter === 'freemium' && !/freemium/.test(a.pricing)) return false
          if (!q) return true
          return (
            (a.name || '').toLowerCase().includes(q)
            || (a.description || '').toLowerCase().includes(q)
            || (a.bestFor || '').toLowerCase().includes(q)
            || (cat.name || '').toLowerCase().includes(q)
          )
        })
        return { ...cat, apis }
      })
      .filter((cat) => cat.apis.length > 0)
  }, [q, pricingFilter])

  const totalShown = filteredCats.reduce((n, c) => n + c.apis.length, 0)

  const collapseItems = filteredCats.map((cat) => ({
    key: cat.name,
    label: (
      <div className="flex items-center gap-2 min-w-0">
        <span className="text-lg">{CATEGORY_ICONS[cat.name] || '📂'}</span>
        <span className="text-white text-sm font-semibold truncate">{cat.name}</span>
        <Badge count={cat.apis.length} style={{ backgroundColor: 'rgba(251,191,36,0.2)', color: '#fbbf24', boxShadow: 'none' }} />
      </div>
    ),
    children: (
      <div className="overflow-x-auto -mx-3">
        <table className="w-full min-w-[560px] text-xs">
          <thead>
            <tr className="text-left text-gray-500 border-b border-white/5">
              <th className="px-3 py-2 font-medium w-1/4">Name</th>
              <th className="px-3 py-2 font-medium">Description</th>
              <th className="px-3 py-2 font-medium w-20">Pricing</th>
              <th className="px-3 py-2 font-medium w-14 text-right">Link</th>
            </tr>
          </thead>
          <tbody>
            {cat.apis.map((a, i) => (
              <tr key={`${a.name}-${i}`} className="border-b border-white/[0.03] hover:bg-white/[0.02] transition-colors">
                <td className="px-3 py-2 align-top">
                  <div className="text-white font-medium">{a.name}</div>
                  {a.categoryPath?.[1] && <div className="text-[10px] text-gray-500 mt-0.5">{a.categoryPath[1]}</div>}
                </td>
                <td className="px-3 py-2 align-top text-gray-400">
                  <div className="line-clamp-2">{a.description || a.bestFor || '—'}</div>
                </td>
                <td className="px-3 py-2 align-top">
                  <PricingTag pricing={a.pricing} />
                  {a.api && <div className="mt-1"><Tag color="blue">API</Tag></div>}
                </td>
                <td className="px-3 py-2 align-top text-right">
                  {a.url && (
                    <Tooltip title={a.url}>
                      <a
                        href={a.url} target="_blank" rel="noopener noreferrer"
                        className="inline-flex items-center gap-1 text-cyan-300 hover:text-cyan-200"
                        aria-label={`Open ${a.name}`}
                      >
                        <LinkOutlined />
                      </a>
                    </Tooltip>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    ),
  }))

  return (
    <div className="luxe-glass rounded-2xl p-4 sm:p-5">
      <div className="flex flex-col sm:flex-row sm:items-center gap-3 mb-4">
        <div className="flex-1">
          <Input
            allowClear
            size="middle"
            prefix={<SearchOutlined className="text-gray-500" />}
            placeholder={`Search ${catalog.stats.total} APIs across ${catalog.stats.categoriesCount} categories…`}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <Segmented
          size="small"
          value={pricingFilter}
          onChange={setPricingFilter}
          options={[
            { label: 'All',      value: 'all' },
            { label: 'Free',     value: 'free' },
            { label: 'Freemium', value: 'freemium' },
            { label: 'Paid',     value: 'paid' },
          ]}
        />
      </div>
      <div className="text-[10px] text-gray-500 mb-2">
        showing {totalShown} of {catalog.stats.total} APIs in {filteredCats.length} categor{filteredCats.length === 1 ? 'y' : 'ies'}
      </div>
      <AnimatePresence mode="wait">
        <motion.div
          key={`${q}::${pricingFilter}`}
          initial={{ opacity: 0, y: 4 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0 }}
          transition={{ duration: 0.2 }}
        >
          {collapseItems.length === 0 ? (
            <Empty description={<span className="text-gray-500">no APIs match your filters</span>} />
          ) : (
            <Collapse
              accordion={false}
              bordered={false}
              size="small"
              items={collapseItems}
              className="osint-collapse"
            />
          )}
        </motion.div>
      </AnimatePresence>
    </div>
  )
}

